"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3806],{32302:e=>{e.exports=JSON.parse('{"functions":[{"name":"create","desc":"Destroys any existing indicator and creates a new anchored, non-colliding,\\nhalf-transparent neon cylinder lying flat. It starts out of sight (100 studs below\\nthe origin) until [AimIndicator.update] moves it.","params":[{"name":"size","desc":"The diameter of the disc, in studs.","lua_type":"number"},{"name":"color","desc":"Defaults to `Color3.fromRGB(255, 80, 60)`.","lua_type":"Color3?"},{"name":"parent","desc":"Defaults to `workspace`.","lua_type":"Instance?"}],"returns":[{"desc":"The indicator part.","lua_type":"BasePart"}],"function_type":"static","source":{"line":36,"path":"src/AimIndicator.luau"}},{"name":"update","desc":"Moves the indicator so it lies flat on `position`, raised 0.15 studs to avoid\\nz-fighting with the ground. Does nothing if no indicator exists.","params":[{"name":"position","desc":"A position on the ground.","lua_type":"Vector3"}],"returns":[],"function_type":"static","source":{"line":63,"path":"src/AimIndicator.luau"}},{"name":"destroy","desc":"Destroys the current indicator, if there is one.","params":[],"returns":[],"function_type":"static","source":{"line":75,"path":"src/AimIndicator.luau"}}],"properties":[],"types":[],"name":"AimIndicator","desc":"A single flat, neon disc that marks where an ability will land. The module keeps\\none indicator at a time: creating a new one destroys the previous one.\\n\\n```lua\\nAimIndicator.create(8, Color3.fromRGB(80, 160, 255))\\n\\nRunService.RenderStepped:Connect(function()\\n\\tAimIndicator.update(mouseHitPosition)\\nend)\\n\\n-- Later\\nAimIndicator.destroy()\\n```","source":{"line":19,"path":"src/AimIndicator.luau"}}')}}]);